function validate([rolls, k]) {
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is an integer from 1 to 10^5.';
  if (rolls.length < 1 || rolls.length > 100000) return 'rolls needs 1 to 10^5 values.';
  if (rolls.some(v => !Number.isInteger(v) || v < 1 || v > k)) return 'Each roll is an integer from 1 to k.';
  return null;
}

