function shortestSequence(rolls, k) {
  const contains = sequence => {
    let at = 0;
    for (const roll of rolls) if (at < sequence.length && roll === sequence[at]) at++;
    return at === sequence.length;
  };
  for (let len = 1; ; len++) {
    // Count through every sequence of length len over the faces 1..k.
    const sequence = new Array(len).fill(1);
    for (;;) {
      if (!contains(sequence)) return len;
      let pos = len - 1;
      while (pos >= 0 && sequence[pos] === k) sequence[pos--] = 1;
      if (pos < 0) break;
      sequence[pos]++;
    }
  }
}

