function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const k = pick(1, 4), n = pick(1, 8);
    return [Array.from({ length: n }, () => pick(1, k)), k];
  }
  const k = [1, 2, 7, 40, 2500][pick(0, 4)];
  return [Array.from({ length: 2000 }, () => pick(1, Math.min(k, 2000))), k];
}
